FV/E2E/SemanticABIBoundary.lean.hasTls_of_vcode_semantic_abi:
theorem hasTls_of_vcode_semantic_abi {f : Clif.Function} {k : Nat} {vc vcp : VCode}
    {rf : RFunc} {af : AFunc} {fa : FnAsm} {fb : FnBin}
